import {quizTrophies,trophyProgress,sortQuizTrophies} from './quiz-trophies-core.mjs';
import {quizTime} from './quiz-records-core.mjs';
const mysteryMarkup='<svg viewBox="0 0 80 88" aria-hidden="true"><path d="M20 35v-9a20 20 0 0 1 40 0v9M14 35h52v43H14z"/><path d="M35 49a6 6 0 1 1 10 5c-3 2-5 3-5 7"/><circle cx="40" cy="68" r="1"/></svg>';
